.primary:disabled, .trigger:disabled { cursor: not-allowed; opacity: .52; }
.secondary { border-color: var(--border); border-radius: var(--radius-full); corner-shape: round; background: var(--surface); }
.secondary .primary, .secondary .trigger { min-height: var(--control-height-sm); background: var(--surface); color: var(--foreground); }
.secondary .primary { min-width: 142px; border-radius: var(--radius-full) 0 0 var(--radius-full); corner-shape: round; padding-inline: var(--space-group); font-size: var(--text-xs); }
.secondary .trigger { width: 32px; border-left-color: var(--border-subtle); border-radius: 0 var(--radius-full) var(--radius-full) 0; corner-shape: round; }
.secondary .primary:active:not(:disabled), .secondary .trigger:active:not(:disabled), .secondary .trigger[data-state="open"] { background: color-mix(in oklab, var(--surface-muted), var(--border) 55%); }
.icon { display: inline-flex; }
.srOnly { position: absolute; width: 1px; height: 1px; overflow: hidden; clip: rect(0 0 0 0); white-space: nowrap; }
/* The menu grows from the trigger edge: offset toward the trigger, scale from the Radix origin, fade quickly; it leaves faster than it arrives.
   Transitions instead of keyframes, so a close that interrupts the open reverses from where the menu is instead of snapping to rest first. */
.menu { --menu-x: 0px; --menu-y: -5px; position: relative; z-index: var(--layer-dropdown); min-width: min(12rem, var(--radix-dropdown-menu-content-available-width)); max-width: var(--radix-dropdown-menu-content-available-width); padding: var(--space-tight); border: 1px solid var(--border); border-radius: var(--radius-container); corner-shape: var(--corner-shape); background: var(--surface-raised); color: var(--foreground); box-shadow: var(--shadow-floating); transform-origin: var(--radix-dropdown-menu-content-transform-origin); transition: opacity var(--duration-fast) var(--ease-enter), transform var(--duration-spring) var(--ease-spring); }
.menu[data-side="top"] { --menu-y: 5px; }
.menu[data-side="left"] { --menu-x: 5px; --menu-y: 0px; }
.menu[data-side="right"] { --menu-x: -5px; --menu-y: 0px; }
@starting-style {
  .menu[data-state="open"] { opacity: 0; transform: translate(var(--menu-x), var(--menu-y)) scale(.97); }
  .menu[data-state="open"] .item { opacity: 0; transform: translate(calc(var(--menu-x) * .4), calc(var(--menu-y) * .4)); }
}
/* Radix unmounts when the exit animation ends, so a no-op keyframe times the exit while the transition does the visual work. */
.menu[data-state="closed"] { opacity: 0; transform: translate(calc(var(--menu-x) * .5), calc(var(--menu-y) * .5)) scale(.985); transition: opacity var(--duration-instant) var(--ease-standard), transform var(--duration-instant) var(--ease-standard); animation: menu-exit var(--duration-instant) linear both; pointer-events: none; }
.highlight { position: absolute; top: 0; right: var(--space-tight); left: var(--space-tight); border-radius: calc(var(--radius-container) - var(--space-related)); background: var(--surface-muted); opacity: 0; pointer-events: none; transition: background-color var(--duration-fast) var(--ease-standard); }
.highlight[data-tone="danger"] { background: color-mix(in oklab, var(--danger) 8%, var(--surface)); }
/* One highlight glides between items for the pointer and jumps instantly for the keyboard (lib/menu-highlight). */
.item { position: relative; display: flex; min-height: var(--control-height-sm); align-items: center; gap: var(--space-group); padding: 0 var(--space-group); border-radius: calc(var(--radius-container) - var(--space-related)); corner-shape: var(--corner-shape); font-size: var(--text-sm); cursor: pointer; outline: none; transition: opacity var(--duration-standard) var(--ease-enter) calc(min(var(--i, 0), 4) * 35ms), transform var(--duration-standard) var(--ease-enter) calc(min(var(--i, 0), 4) * 35ms); }
.item[data-disabled] { cursor: default; opacity: .45; }
.destructive { color: var(--danger); }
@keyframes menu-exit { to { --menu-exit: 1; } }
@media (prefers-reduced-motion: reduce) {
  .group, .primary, .trigger, .chevron { transition: none; }
  .group:has(> .primary:active:not(:disabled)) { transform: none; }
  .item { transition: none; }
  .menu, .menu[data-state="closed"] { transform: none; transition: opacity var(--duration-instant) linear; }
}

"use client";

import { useRef } from "react";
import type { FocusEvent, MouseEvent } from "react";
import { motion, useReducedMotion } from "motion/react";
import { FluidHoverHighlight, useFluidHover, type FluidRect } from "./fluid-hover";
import { motionTokens } from "./motion-tokens";

/** A fluid hover highlight in a menu: where it sits, whether it travels, its pointer session, and its tone. */
type FluidHighlight = { rect: FluidRect | null; glide: boolean; session: number; danger: boolean };
/** A marker positioned by top and height only (a list's current-page marker). */
type BarHighlight = { top: number; height: number; danger: boolean; glide: boolean };

const ITEMS = '[role="menuitem"], [role="menuitemcheckbox"], [role="menuitemradio"], [role="option"]';

/**
 * Fluid hover for a Radix menu or listbox (lib/fluid-hover): the item nearest the pointer is lit, gaps and padding
 * included, a click in a gap picks the lit item, and the keyboard moves the highlight with Radix's focus, without travel.
 * Spread `contentProps` on the content, call `reset` when it opens, and render `<MenuHighlight state={highlight} … />`
 * as its first child. Items mark a destructive tone with `data-tone="danger"`.
 */
export function useMenuHighlight(itemSelector = ITEMS) {
  // The content element is taken from its own events, so the hook never competes with the content's ref.
  const content = useRef<HTMLElement | null>(null);
  const hover = useFluidHover(content, { items: itemSelector });
  const own = (event: { currentTarget: EventTarget }) => { content.current = event.currentTarget as HTMLElement; };
  const { handlers } = hover;
  const highlight: FluidHighlight = { rect: hover.rect, glide: hover.glide, session: hover.session, danger: hover.item?.dataset.tone === "danger" };
  return {
    highlight,
    reset: hover.reset,
    contentProps: {
      onMouseEnter: (event: MouseEvent<HTMLElement>) => { own(event); handlers.onMouseEnter(); },
      onMouseMove: (event: MouseEvent<HTMLElement>) => { own(event); handlers.onMouseMove(event); },
      onMouseLeave: handlers.onMouseLeave,
      onKeyDownCapture: handlers.onKeyDownCapture,
      onFocus: (event: FocusEvent<HTMLElement>) => { own(event); handlers.onFocus(event); },
      onBlur: handlers.onBlur,
      onClick: (event: MouseEvent<HTMLElement>) => { own(event); handlers.onClick(event); },
    },
  };
}

/** The highlight itself: the fluid hover highlight, or a marker that moves by top and height (a current-page marker). */
export function MenuHighlight({ state, className }: { state: FluidHighlight | BarHighlight | null; className?: string }) {
  if (state && "session" in state) return <FluidHoverHighlight hover={state} className={className} tone={state.danger ? "danger" : undefined} />;
  return <BarMarker state={state} className={className} />;
}

function BarMarker({ state, className }: { state: BarHighlight | null; className?: string }) {
  const reduced = useReducedMotion();
  return <motion.span className={className} data-tone={state?.danger ? "danger" : undefined} aria-hidden="true" initial={false}
    animate={state ? { y: state.top, height: state.height, opacity: 1 } : { opacity: 0 }}
    transition={{ default: state?.glide && !reduced ? motionTokens.spring.fast : { duration: 0 }, opacity: { duration: reduced ? 0 : motionTokens.duration.fast } }} />;
}

"use client";

/**
 * Fluid hover: in a set of items (a menu, a list, tabs, a grid), the item nearest the pointer is lit, even while the
 * pointer is in a gap, the padding or past the last item, and one highlight springs between items. A click in a gap goes
 * to the lit item, so what is lit is what a click hits. A new pointer entry fades the highlight in where it lands instead
 * of sliding it over from the last item. The keyboard moves it without travel, and reduced motion keeps the fade but
 * drops the travel.
 *
 *   const list = useRef<HTMLUListElement>(null);
 *   const hover = useFluidHover(list, { items: "[data-item]" });
 *   <ul ref={list} className={styles.list} {...hover.handlers}>      // .list { position: relative }
 *     <FluidHoverHighlight hover={hover} className={styles.highlight} />
 *     …items…
 *   </ul>
 *
 * Adapted from Fluid Functionalism's use-fluid-hover and fluid-hover-highlight by Micka Touillaud (MIT),
 * https://github.com/mickadesign/fluid-functionalism. Items are found by a selector instead of registering themselves,
 * so a component adopts it without changing its items.
 */
import { useEffect, useEffectEvent, useRef, useState } from "react";
import type { FocusEvent, MouseEvent, PointerEvent, RefObject } from "react";
import { AnimatePresence, motion, useReducedMotion } from "motion/react";
import { motionTokens } from "./motion-tokens";

/** An item's box in the container's own layout space (unaffected by transforms or scrolling). */
export interface FluidRect { top: number; left: number; width: number; height: number }

export interface FluidHoverState {
  /** Where the highlight sits, or null when nothing is lit. */
  rect: FluidRect | null;
  /** The lit item. */
  item: HTMLElement | null;
  /** False when the highlight should jump (keyboard, a resize) rather than travel. */
  glide: boolean;
  /** Steps on each new pointer entry, so the highlight fades in where it lands. */
  session: number;
}

export interface FluidHoverOptions {
  /** Selector for the items inside the container. */
  items: string;
  /** "y" for lists (default), "x" for a row of tabs, "xy" for grids. */
  axis?: "x" | "y" | "xy";
  /** Items the highlight skips (and a gap click never activates). Defaults to disabled or aria-disabled items. */
  isItemDisabled?: (item: HTMLElement) => boolean;
  /** "skip" (default) lights the nearest enabled item even over a disabled one; "clear" lights nothing over a disabled item (a calendar's unavailable days). */
  disabled?: "skip" | "clear";
  /** Route a click in a gap to the lit item. On by default; turn it off where empty space should stay inert. */
  gapClick?: boolean;
  /** Light the item that receives keyboard focus. On by default. */
  followFocus?: boolean;
}

const defaultDisabled = (item: HTMLElement) =>
  item.matches(":disabled, [aria-disabled='true'], [data-disabled]");

/** Controls that sit between items keep their own clicks. */
const CONTROL = "input, textarea, select, button, a, summary, [contenteditable], [role='textbox'], [role='searchbox'], [role='button']";

/** The item's box relative to the container, summing offsets through positioned ancestors in between. */
export function rectOf(item: HTMLElement, container: HTMLElement): FluidRect {
  let top = item.offsetTop, left = item.offsetLeft;
  let parent = item.offsetParent as HTMLElement | null;
  while (parent && parent !== container && container.contains(parent)) {
    top += parent.offsetTop + parent.clientTop;
    left += parent.offsetLeft + parent.clientLeft;
    parent = parent.offsetParent as HTMLElement | null;
  }
  return { top, left, width: item.offsetWidth, height: item.offsetHeight };
}

/**
 * The item the pointer is inside, or else the one whose edge is nearest along the axis (both axes for a grid). Edges, not
 * centres, so a gap next to a wide item still lights the item the pointer is closer to.
 */
export function pickNearest(items: HTMLElement[], x: number, y: number, axis: "x" | "y" | "xy"): HTMLElement | null {
  let nearest: HTMLElement | null = null, best = Infinity;
  for (const item of items) {
    const r = item.getBoundingClientRect();
    if (!r.width && !r.height) continue;
    if (x >= r.left && x <= r.right && y >= r.top && y <= r.bottom) return item;
    const dx = Math.max(r.left - x, 0, x - r.right), dy = Math.max(r.top - y, 0, y - r.bottom);
    const distance = axis === "x" ? dx : axis === "y" ? dy : Math.hypot(dx, dy);
    if (distance < best) { best = distance; nearest = item; }
  }
  return nearest;
}

/** Hands a gap click to the item as a real mouse click (detail, modifiers and coordinates kept), so the item reads it as a pointer press, not a keyboard one. */
function forwardClick(item: HTMLElement, event: MouseEvent<HTMLElement>) {
  const { detail, clientX, clientY, screenX, screenY, ctrlKey, shiftKey, altKey, metaKey, button, buttons } = event;
  item.dispatchEvent(new globalThis.MouseEvent("click", { bubbles: true, cancelable: true, composed: true, view: window, detail, clientX, clientY, screenX, screenY, ctrlKey, shiftKey, altKey, metaKey, button, buttons }));
}

/** Whether an event happened inside the element whose handler hears it, not in a portalled child (a submenu, a tooltip). */
const isOwn = (event: { currentTarget: EventTarget; target: EventTarget }) =>
  !(event.currentTarget instanceof Node) || !(event.target instanceof Node) || event.currentTarget.contains(event.target);

export function useFluidHover<T extends HTMLElement>(container: RefObject<T | null>, options: FluidHoverOptions) {
  const { items: selector, axis = "y", isItemDisabled = defaultDisabled, disabled = "skip", gapClick = true, followFocus = true } = options;
  const [state, setState] = useState<FluidHoverState>({ rect: null, item: null, glide: false, session: 0 });
  const current = useRef(state);
  const pointer = useRef(false);
  const entering = useRef(false);
  const frame = useRef(0);

  function commit(next: FluidHoverState) {
    const prev = current.current;
    if (prev.item === next.item && prev.session === next.session && sameRect(prev.rect, next.rect)) return;
    current.current = next;
    setState(next);
  }

  function light(item: HTMLElement | null, glide: boolean) {
    const root = container.current;
    if (!root || !item) return commit({ ...current.current, rect: null, item: null, glide });
    let session = current.current.session;
    if (entering.current) { entering.current = false; session += 1; }
    commit({ rect: rectOf(item, root), item, glide: glide && session === current.current.session, session });
  }

  const enabledItems = () => {
    const root = container.current;
    return root ? [...root.querySelectorAll<HTMLElement>(selector)].filter(item => !isItemDisabled(item)) : [];
  };

  // The lit item can move under a still highlight (a resize, content above it changing): follow it without travel.
  const follow = useEffectEvent(() => { const { item } = current.current; if (item?.isConnected) light(item, false); });
  useEffect(() => {
    const root = container.current;
    if (!root || typeof ResizeObserver === "undefined") return;
    const observer = new ResizeObserver(() => follow());
    observer.observe(root);
    return () => observer.disconnect();
  }, [container]);
  useEffect(() => () => cancelAnimationFrame(frame.current), []);

  const handlers = {
    onMouseEnter: () => { entering.current = true; },
    onMouseMove: (event: MouseEvent<T>) => {
      if (!isOwn(event)) return;
      pointer.current = true;
      const { clientX, clientY } = event;
      cancelAnimationFrame(frame.current);
      frame.current = requestAnimationFrame(() => {
        const over = disabled === "clear" ? document.elementFromPoint(clientX, clientY)?.closest<HTMLElement>(selector) : null;
        light(over && isItemDisabled(over) ? null : pickNearest(enabledItems(), clientX, clientY, axis), true);
      });
    },
    onMouseLeave: () => { cancelAnimationFrame(frame.current); entering.current = false; light(null, false); },
    onKeyDownCapture: () => { pointer.current = false; },
    onFocus: (event: FocusEvent<T>) => {
      if (!followFocus || pointer.current || !isOwn(event)) return;
      const item = event.target instanceof HTMLElement ? event.target.closest<HTMLElement>(selector) : null;
      if (item && container.current?.contains(item) && !isItemDisabled(item)) light(item, false);
    },
    onBlur: (event: FocusEvent<T>) => {
      if (!pointer.current && !event.currentTarget.contains(event.relatedTarget as Node | null)) light(null, false);
    },
    onClick: (event: MouseEvent<T>) => {
      if (!gapClick || !isOwn(event)) return;
      const target = event.target as Element;
      if (!target.isConnected || target.closest(selector) || target.closest(CONTROL)) return;
      const { item } = current.current;
      if (item?.isConnected && !isItemDisabled(item)) forwardClick(item, event);
    },
  };

  /** Clears the highlight at once, such as when a menu opens again. */
  const reset = () => { cancelAnimationFrame(frame.current); entering.current = true; light(null, false); };

  return { ...state, handlers, reset, light };
}

export interface NearestItemOptions extends Omit<FluidHoverOptions, "followFocus"> {
  /** Called with the nearest enabled item as the mouse moves over the container. */
  onPick: (item: HTMLElement) => void;
}

/**
 * Fluid hover's picking without its highlight, for a list that already keeps its own active item and highlight (a listbox
 * with aria-activedescendant, a roving list): the mouse picks the nearest enabled item, gaps and padding included, and a
 * click in a gap goes to that item. Spread the result on the container.
 */
// A hook only so callbacks that touch refs can be passed during render; it keeps no state.
export function useNearestItem<T extends HTMLElement>({ items: selector, axis = "y", isItemDisabled = defaultDisabled, gapClick = true, onPick }: NearestItemOptions) {
  const nearest = (event: MouseEvent<T>) => {
    if (!isOwn(event)) return null;
    const items = [...event.currentTarget.querySelectorAll<HTMLElement>(selector)].filter(item => !isItemDisabled(item));
    return pickNearest(items, event.clientX, event.clientY, axis);
  };
  return {
    onPointerMove: (event: PointerEvent<T>) => { if (event.pointerType !== "mouse") return; const item = nearest(event); if (item) onPick(item); },
    onClick: (event: MouseEvent<T>) => {
      if (!gapClick) return;
      const target = event.target as Element;
      if (!target.isConnected || target.closest(selector) || target.closest(CONTROL)) return;
      const item = nearest(event);
      if (item) forwardClick(item, event);
    },
  };
}

const sameRect = (a: FluidRect | null, b: FluidRect | null) =>
  a === b || (!!a && !!b && a.top === b.top && a.left === b.left && a.width === b.width && a.height === b.height);

export interface FluidHoverHighlightProps {
  /** The state from useFluidHover (or any { rect, glide, session }). */
  hover: Pick<FluidHoverState, "rect" | "glide" | "session">;
  /** Radius, fill, z-index. The container must be position: relative; the highlight is placed at its top-left corner. */
  className?: string;
  /** Extra attributes for styling, such as data-tone. */
  tone?: string;
}

/** The one highlight a fluid hover set renders: it springs between items on transforms, and fades in and out. */
export function FluidHoverHighlight({ hover, className, tone }: FluidHoverHighlightProps) {
  const reduced = useReducedMotion() ?? false;
  const { rect, glide, session } = hover;
  const place = rect ? { x: rect.left, y: rect.top, width: rect.width, height: rect.height } : undefined;
  return (
    <AnimatePresence initial={false}>
      {place ? (
        <motion.span key={session} className={className} data-tone={tone} aria-hidden="true"
          style={{ position: "absolute", top: 0, left: 0, pointerEvents: "none" }}
          initial={{ opacity: 0, ...place }}
          animate={{ opacity: 1, ...place }}
          exit={{ opacity: 0, transition: motionTokens.spring.fast.exit }}
          transition={{ default: glide && !reduced ? motionTokens.spring.fast : { duration: 0 }, opacity: { duration: motionTokens.duration.fast } }} />
      ) : null}
    </AnimatePresence>
  );
}

"use client";
import { useEffect, useLayoutEffect, useMemo, useRef, useState } from "react";
import { AnimatePresence, animate, motion, useReducedMotion, type AnimationPlaybackControls } from "motion/react";
import { motionTokens } from "../lib/motion-tokens";
import styles from "./text-morph.module.css";

/**
 * Morphs one short label into the next in place. Letters both strings share glide to their new positions, new letters sharpen in, removed letters blur away,
 * and the width follows on a spring so the surrounding layout glides instead of jumping. Use it for status words that change a few letters at a time,
 * such as Publish, Publishing, and Published, or Follow and Following. It stays on one line, and assistive technology reads the plain text.
 */
export interface TextMorphProps { children: string; as?: "span" | "div" | "p" | "strong" | "h1" | "h2" | "h3"; className?: string; id?: string }

const enter = [...motionTokens.ease.enter] as [number, number, number, number];
const standard = [...motionTokens.ease.standard] as [number, number, number, number];
const blurred = `blur(${motionTokens.blur.soft}px)`;
/** Lets leaving letters start to clear before the first new letter sharpens in their place. */
const HANDOFF = .05;
/** Letters match by character and occurrence, so the second "i" in one string pairs with the second "i" in the next. */
function toGlyphs(text: string) {
  const seen = new Map<string, number>();
  return Array.from(text).map(char => { const count = seen.get(char) ?? 0; seen.set(char, count + 1); return { char, key: `${char}-${count}` }; });
}
const measure = (element: HTMLElement) => parseFloat(getComputedStyle(element).width);

export function TextMorph({ children, as = "span", className, id }: TextMorphProps) {
  const Tag = as;
  const reduced = useReducedMotion();
  const frame = useRef<HTMLSpanElement>(null);
  const track = useRef<HTMLSpanElement>(null);
  const width = useRef(0);
  const sizing = useRef<AnimationPlaybackControls | null>(null);
  const glyphs = useMemo(() => toGlyphs(children), [children]);
  // The previous label tells which letters are new, so only they stagger, in reading order, however far along the word they sit.
  const [labels, setLabels] = useState({ current: children, previous: children });
  if (labels.current !== children) setLabels({ current: children, previous: labels.current });
  const kept = useMemo(() => new Set(toGlyphs(labels.previous).map(glyph => glyph.key)), [labels.previous]);
  let entering = 0;

  // The frame holds an explicit width so a new label never snaps it; the spring then follows the track, which already has the new letters in place.
  useLayoutEffect(() => {
    const frameElement = frame.current, trackElement = track.current;
    if (!frameElement || !trackElement) return;
    const next = measure(trackElement);
    if (!Number.isFinite(next)) return;
    if (width.current && Math.abs(next - width.current) > .5 && !reduced) sizing.current = animate(frameElement, { width: next }, motionTokens.spring.morph);
    else { sizing.current?.stop(); frameElement.style.width = `${next}px`; }
    width.current = next;
  }, [children, reduced]);
  // Font loading or a responsive font size changes the width without a new label: follow it immediately.
  useEffect(() => {
    const frameElement = frame.current, trackElement = track.current;
    if (!frameElement || !trackElement || typeof ResizeObserver === "undefined") return;
    const observer = new ResizeObserver(() => {
      const next = measure(trackElement);
      if (!Number.isFinite(next) || Math.abs(next - width.current) < .5) return;
      sizing.current?.stop(); frameElement.style.width = `${next}px`; width.current = next;
    });
    observer.observe(trackElement);
    return () => observer.disconnect();
  }, []);

  return <Tag id={id} className={className}>
    <span className={styles.srOnly}>{children}</span>
    <span ref={frame} className={styles.frame} aria-hidden="true"><span ref={track} className={styles.track}>
      <AnimatePresence mode="popLayout" initial={false}>
        {glyphs.map(({ char, key }) => { const order = kept.has(key) ? 0 : entering++; return <motion.span key={key} layout="position" className={styles.glyph}
          initial={reduced ? false : { opacity: 0, scale: .8, y: "0.14em", filter: blurred }}
          animate={{ opacity: 1, scale: 1, y: "0em", filter: "blur(0px)" }}
          exit={reduced ? { opacity: 0, transition: { duration: 0 } } : { opacity: 0, scale: .86, y: "-0.1em", filter: blurred, transition: { duration: motionTokens.duration.exit, ease: standard } }}
          transition={reduced ? { duration: 0 } : { layout: motionTokens.spring.morph, default: { duration: motionTokens.duration.standard + .04, ease: enter, delay: HANDOFF + Math.min(order, 8) * motionTokens.stagger.char * 2 } }}>
          {char === " " ? "\u00a0" : char}
        </motion.span>; })}
      </AnimatePresence>
    </span></span>
  </Tag>;
}

export default TextMorph;

/* The frame carries the animated width. Its mask reveals new letters through a soft trailing edge as it grows and fades leaving ones as it shrinks.
   Padding with matching negative margins gives the mask room for blur and descenders without changing layout; the edge sits entirely in that room, so resting text is never dimmed.
   The track always starts at the frame's leading edge, even in centered text: otherwise it would recenter inside the old width and leaving letters would jump. */
.frame.frame, .frame { position: relative; display: inline-block; box-sizing: content-box; padding: .5em .5em .5em .2em; margin: -.5em -.5em -.5em -.2em; text-align: start; white-space: nowrap; mask-image: linear-gradient(90deg, #000 calc(100% - .5em), transparent); }
/* The track sizes to the letters in flow. Leaving letters are taken out of flow and positioned against it. */
.track { position: relative; display: inline-block; white-space: nowrap; }
.glyph { display: inline-block; white-space: pre; transform-origin: 50% 60%; }
.srOnly { position: absolute; width: 1px; height: 1px; margin: -1px; padding: 0; overflow: hidden; clip-path: inset(50%); white-space: nowrap; border: 0; user-select: none; }
